-- ============================================
-- LUMA — Thème 1 (Restaurant) : scénario MOYEN 1/3 x4 — Une réservation compliquée
-- ============================================


update scenarios set content = '{"characters": {"staff": "l''hôte/hôtesse"}, "start_node": "n1", "nodes": {"n1": {"speaker": "staff", "text": "Good afternoon, thank you for calling The Olive Branch. How can I help?", "text_fr": "Bon après-midi, merci d''appeler The Olive Branch. Comment puis-je vous aider ?", "choices": [{"text": "I''d like to book a table for four, tonight at 8pm.", "text_fr": "J''aimerais réserver une table pour quatre, ce soir à 20h.", "next": "n2"}, {"text": "I''m calling to check if you have availability this weekend.", "text_fr": "J''appelle pour voir si vous avez de la disponibilité ce week-end.", "next": "n2b"}]}, "n2": {"speaker": "staff", "text": "Let me check... I''m sorry, we''re fully booked at 8pm tonight.", "text_fr": "Laissez-moi vérifier... Je suis désolé, on est complet à 20h ce soir.", "choices": [{"text": "Is there any other time available tonight?", "text_fr": "Il y a un autre créneau disponible ce soir ?", "next": "n3"}, {"text": "That''s a shame — could you suggest a similar restaurant nearby?", "text_fr": "C''est dommage — vous pourriez suggérer un restaurant similaire à proximité ?", "next": "n3b"}]}, "n2b": {"speaker": "staff", "text": "We do, but Saturday evening is filling up fast. What time were you thinking?", "text_fr": "Oui, mais samedi soir se remplit vite. Vous pensiez à quelle heure ?", "choices": [{"text": "Around 7:30pm for four people.", "text_fr": "Vers 19h30 pour quatre personnes.", "next": "n3c"}]}, "n3": {"speaker": "staff", "text": "We have a table at 6pm, or another at 9:30pm. Would either work?", "text_fr": "On a une table à 18h, ou une autre à 21h30. Est-ce que l''un des deux vous convient ?", "choices": [{"text": "6pm works better for us actually.", "text_fr": "18h nous arrange mieux en fait.", "next": "n4"}, {"text": "9:30pm is quite late, but we could manage.", "text_fr": "21h30 c''est assez tard, mais on pourrait s''arranger.", "next": "n4b"}, {"text": "Neither really works — do you have anything else?", "text_fr": "Aucun des deux ne convient vraiment — vous avez autre chose ?", "next": "n3d"}]}, "n3b": {"speaker": "staff", "text": "Of course — La Piazza just down the street often has last-minute openings.", "text_fr": "Bien sûr — La Piazza juste en bas de la rue a souvent des places de dernière minute.", "choices": [{"text": "Thank you, I''ll try there instead.", "text_fr": "Merci, je vais essayer là-bas plutôt.", "next": "end_elsewhere"}, {"text": "Actually, could you put us on a waitlist here instead?", "text_fr": "En fait, vous pourriez nous mettre sur liste d''attente ici plutôt ?", "next": "n3d"}]}, "n3c": {"speaker": "staff", "text": "Let me check Saturday... yes, I can hold 7:30pm for four. Shall I confirm?", "text_fr": "Laissez-moi vérifier samedi... oui, je peux garder 19h30 pour quatre. Je confirme ?", "choices": [{"text": "Yes, please confirm that.", "text_fr": "Oui, confirmez ça s''il vous plaît.", "next": "n5"}]}, "n3d": {"speaker": "staff", "text": "I can put you on our waitlist — we sometimes get cancellations.", "text_fr": "Je peux vous mettre sur liste d''attente — on a parfois des annulations.", "choices": [{"text": "That would be great, please add us.", "text_fr": "Ce serait super, ajoutez-nous s''il vous plaît.", "next": "n4c"}]}, "n4": {"speaker": "staff", "text": "Perfect, I''ll book that — 6pm for four people, under what name?", "text_fr": "Parfait, je réserve ça — 18h pour quatre personnes, à quel nom ?", "choices": [{"text": "Under the name Martin, please.", "text_fr": "Au nom de Martin, s''il vous plaît.", "next": "n5"}]}, "n4b": {"speaker": "staff", "text": "Understood, I''ll note that as a possibility. Shall I confirm 9:30pm?", "text_fr": "Compris, je note ça comme possibilité. Je confirme 21h30 ?", "choices": [{"text": "Yes, let''s confirm that time.", "text_fr": "Oui, confirmons cet horaire.", "next": "n5"}, {"text": "Actually, let me check with my group first and call back.", "text_fr": "En fait, laissez-moi vérifier avec mon groupe et je rappelle.", "next": "end_callback"}]}, "n4c": {"speaker": "staff", "text": "You''re second on the list right now. I''ll call if a table opens up.", "text_fr": "Vous êtes deuxième sur la liste actuellement. Je vous appelle si une table se libère.", "choices": [{"text": "Thank you, I appreciate you trying.", "text_fr": "Merci, j''apprécie que vous essayiez.", "next": "end_waitlist"}]}, "n5": {"speaker": "staff", "text": "Wonderful, and under what name shall I book this?", "text_fr": "Merveilleux, et à quel nom je réserve ça ?", "choices": [{"text": "Under the name Martin, please.", "text_fr": "Au nom de Martin, s''il vous plaît.", "next": "n6"}]}, "n6": {"speaker": "staff", "text": "Perfect, table booked. Any dietary requirements I should note?", "text_fr": "Parfait, table réservée. Des besoins alimentaires particuliers à noter ?", "choices": [{"text": "One of us is vegetarian, if that''s not a problem.", "text_fr": "L''un de nous est végétarien, si ce n''est pas un problème.", "next": "n7"}, {"text": "No, we''re all fine with anything.", "text_fr": "Non, on est tous à l''aise avec tout.", "next": "n7"}]}, "n7": {"speaker": "staff", "text": "Not a problem at all, we have great vegetarian options. See you then!", "text_fr": "Aucun problème, on a d''excellentes options végétariennes. À bientôt !", "choices": [{"text": "Thank you so much, see you tonight.", "text_fr": "Merci beaucoup, à ce soir.", "next": "end_booked"}, {"text": "Perfect, looking forward to it.", "text_fr": "Parfait, j''ai hâte.", "next": "end_booked"}]}, "end_booked": {"speaker": "staff", "text": "Wonderful, we''ll see you soon. Have a great day!", "text_fr": "Merveilleux, à bientôt. Bonne journée !", "end": true, "ending_label": "Réservation confirmée avec succès 📅"}, "end_elsewhere": {"speaker": "staff", "text": "No problem at all, I hope you have a great meal there!", "text_fr": "Aucun problème, j''espère que vous passerez un excellent repas là-bas !", "end": true, "ending_label": "Solution trouvée ailleurs 🔄"}, "end_callback": {"speaker": "staff", "text": "Of course, take your time — just call back when you know!", "text_fr": "Bien sûr, prenez votre temps — rappelez juste quand vous saurez !", "end": true, "ending_label": "Décision reportée, réservation en suspens ⏳"}, "end_waitlist": {"speaker": "staff", "text": "Of course. Fingers crossed something opens up for you!", "text_fr": "Bien sûr. Croisons les doigts pour qu''une place se libère !", "end": true, "ending_label": "Sur liste d''attente, en espérant une place 🤞"}}}'::jsonb, is_playable = true
where title = 'Une réservation compliquée'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));
